{
  "application": "report-generation",
  "case_id": "case-realestate-airbnb-global-cities-en",
  "language": "en",
  "report": {
    "type": "cross-market-analytics-report",
    "audience": "hospitality industry analyst and short-term rental market strategist",
    "tone": "analytical, data-forward, actionable"
  },
  "brief": {
    "title": "Global Airbnb Market Comparison: Pricing, Supply & Guest Demand Across 10 Major Cities",
    "one_liner": "A comprehensive cross-city analysis of Airbnb listings across New York, London, Paris, Tokyo, Barcelona, Los Angeles, Amsterdam, Bangkok, Rome, and Sydney, examining pricing dynamics, room-type distribution, host concentration, and guest engagement patterns.",
    "goal": "Equip the reader with a clear understanding of how Airbnb markets differ across the world's top tourist destinations — identifying which cities command premium pricing, where supply is most concentrated among professional hosts, how room-type mix varies, and where guest demand (as proxied by reviews) is strongest — ultimately enabling data-driven decisions for market entry, investment, or regulatory benchmarking."
  },
  "required_sections": [
    {
      "section_id": "market-overview",
      "title": "Global Market Overview",
      "objective": "Summarize the total number of listings per city, overall price distribution, and room-type breakdown to establish the scale and composition of each market."
    },
    {
      "section_id": "pricing-analysis",
      "title": "Pricing Dynamics Across Cities",
      "objective": "Compare median and average nightly prices by city and room type, identify the most and least expensive markets, and highlight price dispersion within each city."
    },
    {
      "section_id": "supply-structure",
      "title": "Supply Structure & Host Concentration",
      "objective": "Analyze the distribution of room types per city, examine the calculated_host_listings_count to assess professional vs. individual host prevalence, and identify cities with the highest host concentration."
    },
    {
      "section_id": "guest-demand",
      "title": "Guest Demand & Review Activity",
      "objective": "Use number_of_reviews, reviews_per_month, and number_of_reviews_ltm as demand proxies to compare guest engagement across cities and room types, and identify seasonal or recency patterns via last_review dates."
    },
    {
      "section_id": "availability-minimumnights",
      "title": "Availability & Booking Constraints",
      "objective": "Examine availability_365 and minimum_nights distributions across cities to understand listing accessibility and potential regulatory impacts (e.g., high minimum-night requirements suggesting long-term rental regulations)."
    },
    {
      "section_id": "key-takeaways",
      "title": "Key Takeaways & Strategic Implications",
      "objective": "Synthesize findings into actionable insights for investors, hosts, and policymakers, highlighting the most attractive markets and emerging trends."
    }
  ],
  "kpis": [
    {
      "name": "Median Nightly Price by City",
      "description": "The median value of the 'price' column per city, providing a robust central tendency measure for cross-market comparison."
    },
    {
      "name": "Professional Host Share",
      "description": "Percentage of listings in each city where calculated_host_listings_count >= 5, indicating the share of supply controlled by multi-listing (professional) hosts."
    },
    {
      "name": "Average Reviews per Month",
      "description": "Mean of reviews_per_month by city, serving as a proxy for booking frequency and guest demand intensity."
    },
    {
      "name": "Mean Availability (days/year)",
      "description": "Average availability_365 per city, indicating how much of the year listings are open for booking — a signal of commercial intent and regulatory environment."
    },
    {
      "name": "Entire Home Share",
      "description": "Percentage of listings classified as 'Entire home/apt' per city, reflecting the commercialization level of each market."
    }
  ],
  "analysis_dimensions": [
    "city",
    "room_type",
    "price",
    "calculated_host_listings_count",
    "reviews_per_month"
  ]
}

