[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Market Comparison: Pricing, Supply &amp; Guest Demand Across 10 Major Cities</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a3a5c;
    --accent: #e8622a;
    --accent2: #2196a0;
    --bg: #f7f8fa;
    --card: #ffffff;
    --text: #1c2b3a;
    --muted: #6b7a8d;
    --border: #dde2e8;
    --success: #1b8a5a;
    --warn: #d97706;
    --danger: #c0392b;
    --font: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: var(--font); background: var(--bg); color: var(--text); line-height: 1.6; font-size: 15px; }

  /* Cover */
  .cover {
    background: linear-gradient(135deg, var(--primary) 0%, #0d2035 60%, #1a4a6e 100%);
    color: white;
    padding: 80px 60px 60px;
    position: relative;
    overflow: hidden;
  }
  .cover::before {
    content: '';
    position: absolute; top: -100px; right: -100px;
    width: 500px; height: 500px;
    border-radius: 50%;
    background: rgba(255,255,255,0.03);
  }
  .cover::after {
    content: '';
    position: absolute; bottom: -80px; left: -80px;
    width: 350px; height: 350px;
    border-radius: 50%;
    background: rgba(232,98,42,0.08);
  }
  .cover-tag { font-size: 11px; letter-spacing: 2.5px; text-transform: uppercase; color: rgba(255,255,255,0.55); margin-bottom: 18px; }
  .cover h1 { font-size: 38px; font-weight: 700; line-height: 1.2; margin-bottom: 16px; max-width: 700px; }
  .cover h1 span { color: #f4a261; }
  .cover-sub { font-size: 17px; color: rgba(255,255,255,0.75); max-width: 600px; margin-bottom: 40px; }
  .cover-meta { display: flex; gap: 40px; flex-wrap: wrap; margin-top: 20px; }
  .cover-meta-item label { display: block; font-size: 10px; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.45); margin-bottom: 4px; }
  .cover-meta-item span { font-size: 14px; color: rgba(255,255,255,0.85); }
  .cover-accent-bar { height: 4px; width: 60px; background: var(--accent); border-radius: 2px; margin-bottom: 32px; }

  /* Layout */
  .container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }
  .section { padding: 56px 0 40px; }
  .section + .section { border-top: 1px solid var(--border); }

  /* Section headers */
  .section-label { font-size: 11px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--accent); font-weight: 600; margin-bottom: 6px; }
  .section-title { font-size: 26px; font-weight: 700; color: var(--primary); margin-bottom: 10px; }
  .section-desc { color: var(--muted); font-size: 14px; max-width: 720px; margin-bottom: 32px; }

  /* KPI cards */
  .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 40px; }
  .kpi-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px 18px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }
  .kpi-card.blue::before { background: var(--accent2); }
  .kpi-card.green::before { background: var(--success); }
  .kpi-card.warn::before { background: var(--warn); }
  .kpi-card.dark::before { background: var(--primary); }
  .kpi-label { font-size: 11px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--muted); margin-bottom: 8px; }
  .kpi-value { font-size: 28px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 4px; }
  .kpi-sub { font-size: 12px; color: var(--muted); }

  /* Cards / panels */
  .card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 28px;
    margin-bottom: 24px;
  }
  .card-title { font-size: 16px; font-weight: 600; color: var(--primary); margin-bottom: 6px; }
  .card-sub { font-size: 13px; color: var(--muted); margin-bottom: 20px; }

  /* Charts */
  .chart-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 24px; }
  .chart-grid.single { grid-template-columns: 1fr; }
  .chart-grid.three { grid-template-columns: repeat(3, 1fr); }
  .chart-wrap { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 24px; }
  .chart-title { font-size: 14px; font-weight: 600; color: var(--primary); margin-bottom: 4px; }
  .chart-note { font-size: 12px; color: var(--muted); margin-bottom: 16px; }
  .chart-container { position: relative; }

  /* Tables */
  .table-wrap { overflow-x: auto; border-radius: 10px; border: 1px solid var(--border); margin-bottom: 24px; }
  table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
  thead th { background: var(--primary); color: white; padding: 11px 14px; text-align: left; font-weight: 600; font-size: 12px; letter-spacing: 0.5px; white-space: nowrap; }
  thead th:first-child { border-radius: 8px 0 0 0; }
  thead th:last-child { border-radius: 0 8px 0 0; }
  tbody tr { border-bottom: 1px solid var(--border); }
  tbody tr:last-child { border-bottom: none; }
  tbody tr:nth-child(even) { background: #f8f9fb; }
  tbody tr:hover { background: #eef3f9; }
  td { padding: 10px 14px; }
  td.num { text-align: right; font-variant-numeric: tabular-nums; }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 20px; font-size: 11px; font-weight: 600; }
  .badge-red { background: #fde8e8; color: #c0392b; }
  .badge-green { background: #e6f5ee; color: #1b8a5a; }
  .badge-orange { background: #fef3e2; color: #d97706; }
  .badge-blue { background: #e8f4fd; color: #1a6fa0; }
  .badge-gray { background: #f0f2f5; color: #555; }
  .badge-purple { background: #f3eaff; color: #6b3fa0; }

  /* Callout boxes */
  .callout { border-left: 4px solid var(--accent); background: #fff7f3; padding: 16px 20px; border-radius: 0 8px 8px 0; margin-bottom: 20px; }
  .callout.info { border-color: var(--accent2); background: #f0f9fa; }
  .callout.warn { border-color: var(--warn); background: #fffbf0; }
  .callout.success { border-color: var(--success); background: #f0faf5; }
  .callout-title { font-weight: 700; font-size: 13px; margin-bottom: 4px; color: var(--primary); }
  .callout p { font-size: 13.5px; color: var(--text); }

  /* Key takeaways */
  .takeaway-list { counter-reset: takeaway; list-style: none; }
  .takeaway-list li {
    counter-increment: takeaway;
    padding: 18px 20px 18px 68px;
    position: relative;
    border-bottom: 1px solid var(--border);
    font-size: 14.5px;
    line-height: 1.6;
  }
  .takeaway-list li:last-child { border-bottom: none; }
  .takeaway-list li::before {
    content: counter(takeaway);
    position: absolute; left: 18px; top: 50%; transform: translateY(-50%);
    width: 34px; height: 34px; border-radius: 50%;
    background: var(--accent);
    color: white; font-weight: 700; font-size: 16px;
    display: flex; align-items: center; justify-content: center;
  }
  .takeaway-list li strong { color: var(--primary); }

  /* Two-column layout */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

  /* Data note */
  .data-note { background: #f8f9fb; border: 1px solid var(--border); border-radius: 8px; padding: 14px 18px; font-size: 12.5px; color: var(--muted); margin-bottom: 24px; }
  .data-note strong { color: var(--text); }

  /* Mini stat row */
  .stat-row { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 20px; }
  .stat-item { background: var(--card); border: 1px solid var(--border); border-radius: 8px; padding: 14px 18px; flex: 1; min-width: 130px; }
  .stat-item .val { font-size: 22px; font-weight: 700; color: var(--primary); }
  .stat-item .lbl { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 1px; margin-top: 2px; }

  /* Footer */
  .report-footer { background: var(--primary); color: rgba(255,255,255,0.6); padding: 32px 60px; font-size: 12px; display: flex; justify-content: space-between; align-items: center; flex-wrap: gap; margin-top: 60px; }
  .report-footer a { color: rgba(255,255,255,0.8); }

  /* TOC */
  .toc { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 28px; margin: 32px 0; }
  .toc h3 { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--muted); margin-bottom: 16px; }
  .toc ol { list-style: none; counter-reset: toc; }
  .toc li { counter-increment: toc; padding: 7px 0; border-bottom: 1px solid var(--border); display: flex; align-items: center; gap: 12px; }
  .toc li:last-child { border-bottom: none; }
  .toc li::before { content: counter(toc); width: 22px; height: 22px; border-radius: 50%; background: var(--primary); color: white; font-size: 11px; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
  .toc a { text-decoration: none; color: var(--primary); font-size: 14px; font-weight: 500; }
  .toc a:hover { color: var(--accent); }

  /* Pill tags */
  .pill { display: inline-block; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 600; background: #e8eef5; color: var(--primary); margin: 2px; }

  /* Highlight cell */
  .hl-max { background: #d4edda !important; font-weight: 700; color: #155724; }
  .hl-min { background: #ffeeba !important; font-weight: 700; color: #856404; }
  .hl-top { background: #cce5ff !important; font-weight: 700; color: #004085; }

  @media (max-width: 700px) {
    .chart-grid, .two-col, .three-col { grid-template-columns: 1fr; }
    .cover { padding: 40px 24px; }
    .cover h1 { font-size: 26px; }
  }
</style>
</head>
<body>

<!-- ═══════════════════════════════════ COVER ═══════════════════════════════════ -->
<div class="cover">
  <div class="cover-tag">Cross-Market Analytics Report &nbsp;·&nbsp; Hospitality Intelligence</div>
  <div class="cover-accent-bar"></div>
  <h1>Global Airbnb Market Comparison:<br><span>Pricing, Supply &amp; Guest Demand</span><br>Across 7 Major Cities</h1>
  <p class="cover-sub">A comprehensive cross-city analysis of Airbnb listings across London, Paris, Rome, Bangkok, Barcelona, Amsterdam, and Sydney — examining pricing dynamics, room-type distribution, host concentration, and guest engagement patterns.</p>
  <div class="cover-meta">
    <div class="cover-meta-item"><label>Dataset</label><span>50,000 listings · Inside Airbnb</span></div>
    <div class="cover-meta-item"><label>Scrape Date</label><span>March 29, 2026</span></div>
    <div class="cover-meta-item"><label>Audience</label><span>Hospitality Analysts &amp; Market Strategists</span></div>
    <div class="cover-meta-item"><label>Report Date</label><span>April 2026</span></div>
  </div>
</div>

<!-- ═══════════════════════════════════ MAIN CONTAINER ═══════════════════════════════════ -->
<div class="container">

  <!-- Data Scope Note -->
  <div class="data-note" style="margin-top:32px;">
    <strong>Data Scope:</strong> The source dataset advertises 10 cities; the actual extract contains <strong>7 cities</strong> — London, Paris, Rome, Bangkok, Barcelona, Amsterdam, and Sydney. New York, Tokyo, and Los Angeles are absent from the data. Additionally, price data is available for only 5 cities (London, Rome, Barcelona, Bangkok, Amsterdam); <strong>Paris and Sydney have no price entries in this extract</strong> and are excluded from all pricing analyses. Bangkok prices appear to be denominated in <strong>Thai Baht (THB)</strong> rather than USD — values are reported as-is from the source and flagged accordingly. All figures are derived directly from data.csv with no imputation.
  </div>

  <!-- TABLE OF CONTENTS -->
  <div class="toc">
    <h3>Table of Contents</h3>
    <ol>
      <li><a href="#s1">Global Market Overview</a></li>
      <li><a href="#s2">Pricing Dynamics Across Cities</a></li>
      <li><a href="#s3">Supply Structure &amp; Host Concentration</a></li>
      <li><a href="#s4">Guest Demand &amp; Review Activity</a></li>
      <li><a href="#s5">Availability &amp; Booking Constraints</a></li>
      <li><a href="#s6">Key Takeaways &amp; Strategic Implications</a></li>
    </ol>
  </div>

  <!-- ═══════════════════ SECTION 1: GLOBAL MARKET OVERVIEW ═══════════════════ -->
  <section class="section" id="s1">
    <div class="section-label">Section 01</div>
    <div class="section-title">Global Market Overview</div>
    <p class="section-desc">Total listing volumes, room-type composition, and market scale across all seven cities in the dataset.</p>

    <!-- KPI Row -->
    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Total Listings</div>
        <div class="kpi-value">50,000</div>
        <div class="kpi-sub">7 cities · March 2026 scrape</div>
      </div>
      <div class="kpi-card blue">
        <div class="kpi-label">Largest Market</div>
        <div class="kpi-value">London</div>
        <div class="kpi-sub">16,674 listings (33.3% of total)</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Entire Home/Apt</div>
        <div class="kpi-value">73.9%</div>
        <div class="kpi-sub">36,929 of 50,000 listings</div>
      </div>
      <div class="kpi-card green">
        <div class="kpi-label">Private Rooms</div>
        <div class="kpi-value">25.2%</div>
        <div class="kpi-sub">12,623 listings</div>
      </div>
      <div class="kpi-card warn">
        <div class="kpi-label">Hotel Rooms</div>
        <div class="kpi-value">0.6%</div>
        <div class="kpi-sub">294 listings</div>
      </div>
      <div class="kpi-card dark">
        <div class="kpi-label">Shared Rooms</div>
        <div class="kpi-value">0.3%</div>
        <div class="kpi-sub">154 listings</div>
      </div>
    </div>

    <div class="chart-grid">
      <div class="chart-wrap">
        <div class="chart-title">Listings by City</div>
        <div class="chart-note">Total active listing count per city</div>
        <div class="chart-container" style="height:280px;">
          <canvas id="listingsByCity"></canvas>
        </div>
      </div>
      <div class="chart-wrap">
        <div class="chart-title">Room Type Mix — All Cities Combined</div>
        <div class="chart-note">Share of listing type across full dataset</div>
        <div class="chart-container" style="height:280px;">
          <canvas id="roomTypePie"></canvas>
        </div>
      </div>
    </div>

    <!-- Market composition table -->
    <div class="card">
      <div class="card-title">Market Composition by City</div>
      <div class="card-sub">Listing counts and room-type breakdown per city</div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>City</th>
              <th class="num">Total Listings</th>
              <th class="num">Entire Home/Apt</th>
              <th class="num">Private Room</th>
              <th class="num">Hotel Room</th>
              <th class="num">Shared Room</th>
              <th class="num">Entire Home %</th>
            </tr>
          </thead>
          <tbody>
